"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["26252"],{80981(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.grupo_formulario.subitens_fora_do_limite","status":422,"titulo":"A quantidade de campos do grupo est\xe1 fora do limite"},"descricao":{"codigo":"uniplus.grupo_formulario.subitens_fora_do_limite","requisitos":["UNI-REQ-0146"],"oQueAconteceu":["A lista `subitens` de um grupo repet\xedvel, em `grupos`, est\xe1 vazia ou tem mais de 30 campos. Cada ocorr\xeancia do grupo, como um membro da composi\xe7\xe3o familiar (UNI-REQ-0146), coleta de um a 30 campos; o teto de 30 \xe9 da API, e o requisito n\xe3o o declara. A mensagem \xe9 \\"O grupo tem de um a 30 campos por ocorr\xeancia.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `grupos[i].subitens`, uma entrada por grupo recusado, junto das demais recusas da forma do grupo. Na cria\xe7\xe3o e na atualiza\xe7\xe3o de um modelo de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado.","A recusa vale para a lista presente. A propriedade `subitens` ausente ou nula \xe9 recusada antes, com 400 e sem c\xf3digo deste cat\xe1logo. Os campos do grupo tamb\xe9m contam para o teto de itens do formul\xe1rio, que \xe9 [recusado antes](/erros/uniplus.item_formulario.itens_em_excesso), sem a confer\xeancia de cada grupo. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Deixe no grupo ao menos um campo e no m\xe1ximo 30. Para mais campos, divida o grupo em dois ou retire os que n\xe3o s\xe3o necess\xe1rios por ocorr\xeancia."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Grupo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);